// ─── Component ───────────────────────────────────────────────────────────────

interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App({ topBarRight }: AppProps) {
  const [original, setOriginal] = useState(EXAMPLES[0].original);
  const [modified, setModified] = useState(EXAMPLES[0].modified);
  const [menuOpen, setMenuOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) setMenuOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const diff = useMemo(() => diffLines(original, modified), [original, modified]);
  const stats = useMemo(() => diffStats(diff), [diff]);

  const sign = (type: DiffLine['type']) => {
    if (type === 'insert') return '+';
    if (type === 'delete') return '−';
    if (type === 'replace') return '~';
    return ' ';
  };

  return (
    <Wrapper>
      <TopBar>
        <AtlantisLogo onClick={() => { window.location.hash = '#/home'; }} title="Home">
          Atl<span>antis</span>
        </AtlantisLogo>
        <TitleSep>/</TitleSep>
        <AppTitle>Code Diff</AppTitle>
        <StatBadge kind="add">+{stats.added}</StatBadge>
        <StatBadge kind="del">−{stats.removed}</StatBadge>
        <StatBadge kind="mod">~{stats.changed}</StatBadge>
        <Spacer />
        <DropdownWrapper ref={menuRef}>
          <ToolBtn onClick={() => setMenuOpen((o) => !o)}>
            Examples <ChevronDown size={12} />
          </ToolBtn>
          {menuOpen && (
            <DropdownMenu>
              {EXAMPLES.map((ex) => (
                <DropdownItem key={ex.label} onClick={() => { setOriginal(ex.original); setModified(ex.modified); setMenuOpen(false); }}>
                  {ex.label}
                </DropdownItem>
              ))}
            </DropdownMenu>
          )}
        </DropdownWrapper>
        {topBarRight}
      </TopBar>

      <Body>
        <EditorsRow>
          <EditorPane>
            <PaneHeader>Original</PaneHeader>
            <EditorTextArea
              value={original}
              onChange={(e) => setOriginal(e.target.value)}
              placeholder="Paste original text here…"
              spellCheck={false}
            />
          </EditorPane>
          <EditorPane>
            <PaneHeader>Modified</PaneHeader>
            <EditorTextArea
              value={modified}
              onChange={(e) => setModified(e.target.value)}
              placeholder="Paste modified text here…"
              spellCheck={false}
            />
          </EditorPane>
        </EditorsRow>

        <DiffSection>
          {diff.length === 0 ? (
            <EmptyState>
              <GitBranch size={32} strokeWidth={1} />
              <span>Paste text in both panes to see the diff</span>
            </EmptyState>
          ) : (
            <DiffTable>
              <tbody>
                {diff.map((line, i) => (
                  <DiffRow key={i} kind={line.type}>
                    <LineNum>{line.oldNum ?? ' '}</LineNum>
                    <LineNum>{line.newNum ?? ' '}</LineNum>
                    <SignCell kind={line.type}>{sign(line.type)}</SignCell>
                    <CodeCell>
                      {line.type === 'replace'
                        ? <>
                            <span style={{ background: 'rgba(248,113,113,0.2)', borderRadius: 2, textDecoration: 'line-through', opacity: 0.7, marginRight: 4 }}>
                              {line.oldLine}
                            </span>
                            <span style={{ background: 'rgba(63,185,80,0.2)', borderRadius: 2 }}>
                              {line.newLine}
                            </span>
                          </>
                        : line.type === 'delete'
                          ? line.oldLine
                          : line.newLine ?? line.oldLine}
                    </CodeCell>
                  </DiffRow>
                ))}
              </tbody>
            </DiffTable>
          )}
        </DiffSection>
      </Body>
    </Wrapper>
  );
}
